c2:[{direction:'outgoing',text:'HVAC of the Lowcountry LLC: Your $129 seasonal tune-up quote is ready. Open the quote in Client Hub. (Demo only — no live link)'},{direction:'incoming',text:'Looks good. Is next Tuesday available?'}],
